const qa=[
 {topic:'labor',q:'Hợp đồng lao động điện tử có giá trị như bản giấy không?',keys:['lao động','hợp đồng lao động','bản giấy'],title:'Có, nếu được giao kết đúng điều kiện.',answer:'Hợp đồng lao động được giao kết thông qua phương tiện điện tử dưới hình thức thông điệp dữ liệu có giá trị như hợp đồng lao động bằng văn bản. Đồng thời, thông điệp dữ liệu không bị phủ nhận giá trị pháp lý chỉ vì ở dạng điện tử.',cite:'Điều 14 Bộ luật Lao động 2019; Điều 8 Luật Giao dịch điện tử 2023',action:'Bảo đảm nhận diện đúng các bên, thể hiện sự chấp thuận, lưu được bản hoàn chỉnh và có thể truy cập để tham chiếu.'},
 {topic:'labor',q:'Ký hợp đồng lao động bằng OTP có hợp pháp không?',keys:['otp','mã otp'],title:'Có thể hợp pháp, nhưng cần thiết kế chứng cứ tốt.',answer:'OTP có thể là một phương thức thể hiện sự chấp thuận và xác nhận người ký. Giá trị chứng cứ sẽ được xem xét theo độ tin cậy của cách khởi tạo, gửi, nhận, lưu trữ; khả năng bảo đảm tính toàn vẹn và xác định người khởi tạo. OTP không mặc nhiên tương đương chữ ký số.',cite:'Điều 10, 33 Luật Giao dịch điện tử 2023',action:'Lưu nhật ký thời gian, số điện thoại/định danh đã xác minh, nội dung OTP, IP, thiết bị, phiên bản hợp đồng và biên nhận gửi cho người lao động.'},
 {topic:'labor',q:'Doanh nghiệp phải giao bản hợp đồng điện tử cho người lao động thế nào?',keys:['giao bản','người lao động giữ','tải hợp đồng'],title:'Người lao động cần nhận và truy cập được bản đã giao kết.',answer:'Hợp đồng điện tử cần có khả năng truy cập và sử dụng để tham chiếu. Thực tiễn tốt là cấp ngay bản PDF hoàn chỉnh, chứng cứ ký và kênh tải lại ổn định cho người lao động.',cite:'Điều 13 Luật Giao dịch điện tử 2023; Điều 14 Bộ luật Lao động 2019',action:'Gửi email/SMS xác nhận, cho phép tải bản hợp đồng và lưu dấu thời gian bàn giao.'},
 {topic:'trade',q:'Email xác nhận đơn hàng có tạo thành hợp đồng không?',keys:['email','đơn hàng','xác nhận'],title:'Có thể, tùy nội dung và quá trình giao kết.',answer:'Thông điệp dữ liệu có thể đáp ứng yêu cầu về văn bản và không bị phủ nhận giá trị chỉ vì được thể hiện điện tử. Hợp đồng hình thành khi đề nghị và chấp nhận giao kết đáp ứng điều kiện của pháp luật dân sự, thương mại và thỏa thuận giữa các bên.',cite:'Điều 8, 9 Luật Giao dịch điện tử 2023; Bộ luật Dân sự 2015',action:'Kiểm tra người gửi có thẩm quyền, điều khoản cốt lõi đã rõ, thời điểm nhận và chuỗi email có thể xuất trình nguyên vẹn.'},
 {topic:'trade',q:'Hợp đồng thương mại điện tử có bắt buộc dùng chữ ký số?',keys:['bắt buộc','thương mại','chữ ký số'],title:'Không phải mọi hợp đồng đều bắt buộc dùng chữ ký số.',answer:'Các bên có thể lựa chọn phương thức xác nhận phù hợp, trừ khi luật chuyên ngành hoặc thỏa thuận yêu cầu hình thức cụ thể. Chữ ký số làm tăng mức độ tin cậy về danh tính, tính toàn vẹn và thời điểm ký.',cite:'Luật Giao dịch điện tử 2023; Bộ luật Dân sự 2015',action:'Đối chiếu luật chuyên ngành và ma trận thẩm quyền ký; với giao dịch giá trị cao nên dùng chữ ký số kèm dấu thời gian.'},
 {topic:'trade',q:'Thời điểm gửi và nhận hợp đồng điện tử được xác định ra sao?',keys:['thời điểm','gửi','nhận'],title:'Dựa vào hệ thống thông tin được chỉ định và khả năng truy cập.',answer:'Luật quy định riêng về thời điểm, địa điểm gửi và nhận thông điệp dữ liệu; trong giao kết hợp đồng điện tử các quy tắc này tiếp tục được áp dụng.',cite:'Điều 15–18, 37 Luật Giao dịch điện tử 2023',action:'Quy định rõ trong hợp đồng hệ thống nhận, múi giờ, trạng thái “đã nhận” và cơ chế xử lý lỗi.'},
 {topic:'document',q:'Bản scan có được coi là bản gốc điện tử không?',keys:['scan','bản gốc','photo'],title:'Không mặc nhiên; cần xem cách tạo lập và bảo đảm toàn vẹn.',answer:'Thông điệp dữ liệu có thể có giá trị như bản gốc khi bảo đảm tính toàn vẹn kể từ khi được khởi tạo lần đầu và có thể truy cập, sử dụng dưới dạng hoàn chỉnh. Một file scan đơn thuần thường có giá trị chứng cứ nhưng mức tin cậy tùy quy trình.',cite:'Điều 13 Luật Giao dịch điện tử 2023',action:'Giữ file gốc, lịch sử tạo lập, mã băm, dấu thời gian và nhật ký hệ thống; tránh chỉ lưu ảnh chụp rời rạc.'},
 {topic:'document',q:'Dữ liệu hợp đồng phải lưu trữ bao lâu?',keys:['lưu trữ','bao lâu','thời hạn'],title:'Tùy loại hợp đồng và luật chuyên ngành.',answer:'Luật Giao dịch điện tử đặt điều kiện để lưu trữ thông điệp dữ liệu: nội dung truy cập được, đúng khuôn dạng hoặc thể hiện chính xác, và lưu được thông tin nguồn gốc/thời gian. Thời hạn cụ thể cần đối chiếu pháp luật lao động, kế toán, thuế hoặc chuyên ngành.',cite:'Điều 14 Luật Giao dịch điện tử 2023',action:'Lập lịch lưu theo từng hồ sơ, khóa xóa trước hạn và duy trì bản sao dự phòng có kiểm tra toàn vẹn.'},
 {topic:'document',q:'Nhật ký hệ thống có giá trị chứng cứ không?',keys:['nhật ký','log','chứng cứ'],title:'Có thể được dùng để đánh giá giá trị chứng cứ.',answer:'Giá trị chứng cứ của thông điệp dữ liệu được xác định căn cứ vào độ tin cậy của cách khởi tạo, gửi, nhận, lưu trữ; cách bảo đảm và duy trì tính toàn vẹn; cách xác định người khởi tạo cùng yếu tố phù hợp khác.',cite:'Điều 11 Luật Giao dịch điện tử 2023',action:'Bảo vệ log khỏi sửa đổi, đồng bộ thời gian, phân quyền truy cập và thiết lập quy trình trích xuất có xác nhận.'},
 {topic:'signature',q:'Chữ ký điện tử và chữ ký số khác nhau thế nào?',keys:['khác nhau','chữ ký điện tử','chữ ký số'],title:'Chữ ký số là một loại chữ ký điện tử dùng mật mã khóa công khai.',answer:'Chữ ký điện tử là khái niệm rộng về dữ liệu điện tử gắn với thông điệp để xác nhận chủ thể ký và sự chấp thuận. Chữ ký số là chữ ký điện tử sử dụng thuật toán khóa không đối xứng, khóa bí mật và khóa công khai.',cite:'Luật Giao dịch điện tử 2023; Nghị định 23/2025/NĐ-CP',action:'Chọn theo mức rủi ro: OTP/click-wrap cho luồng đơn giản; chữ ký số và dấu thời gian cho giao dịch cần độ tin cậy cao.'},
 {topic:'signature',q:'Chữ ký số hết hạn thì hợp đồng đã ký còn hiệu lực không?',keys:['hết hạn','chứng thư','thu hồi'],title:'Việc hết hạn sau thời điểm ký không tự làm mất hiệu lực hợp đồng.',answer:'Cần xác minh chữ ký hợp lệ tại đúng thời điểm ký. Chứng thư hết hạn sau đó không đồng nghĩa chữ ký trước đó vô hiệu; bằng chứng thời gian và trạng thái chứng thư tại lúc ký có ý nghĩa quan trọng.',cite:'Nghị định 23/2025/NĐ-CP',action:'Lưu chứng thư, trạng thái kiểm tra, chuỗi tin cậy và dấu thời gian cùng hồ sơ hợp đồng.'},
 {topic:'signature',q:'Có cần đóng dấu doanh nghiệp khi đã ký số?',keys:['đóng dấu','con dấu'],title:'Không thể kết luận chung cho mọi giao dịch.',answer:'Giá trị của chữ ký số và yêu cầu về con dấu phụ thuộc chủ thể, thẩm quyền ký, điều lệ/quy chế nội bộ và luật chuyên ngành. Không nên coi hình ảnh con dấu là yếu tố tạo an toàn mật mã.',cite:'Luật Giao dịch điện tử 2023; Nghị định 23/2025/NĐ-CP',action:'Kiểm tra thẩm quyền người ký và quy định chuyên ngành; ưu tiên chứng thư đúng tên chủ thể và quy trình ủy quyền rõ ràng.'}
];
const checklist=[
 ['Đúng chủ thể và thẩm quyền','Đã xác minh danh tính, tư cách pháp lý và quyền ký của mỗi bên.'],['Nội dung và phiên bản cuối','Bản được ký đúng là bản cuối cùng mà các bên đã xem.'],['Thể hiện sự chấp thuận','Có hành động ký/xác nhận rõ ràng, không dùng ô chọn được tích sẵn.'],['Tính toàn vẹn','Có mã băm, chữ ký số hoặc cơ chế phát hiện mọi thay đổi sau khi ký.'],['Mốc thời gian tin cậy','Ghi nhận thời điểm gửi, nhận, ký và múi giờ; cân nhắc dấu thời gian.'],['Hồ sơ chứng cứ','Lưu nhật ký, IP, thiết bị, định danh, kết quả kiểm tra chữ ký/chứng thư.'],['Bàn giao và truy cập','Mỗi bên nhận được bản hoàn chỉnh và có thể tải, đọc để tham chiếu.'],['Dữ liệu cá nhân','Có mục đích, phạm vi, thời hạn xử lý và biện pháp bảo vệ phù hợp.']
];
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
function renderSources(filter=''){const f=filter.toLowerCase();$('#sourceGrid').innerHTML=sources.filter(s=>(s.title+s.desc).toLowerCase().includes(f)).map(s=>`<article class="source-card"><div><div class="kind">${s.kind}</div><h3>${s.title}</h3><p>${s.desc}</p></div><a href="${s.url}" target="_blank" rel="noopener" aria-label="Mở văn bản">↗</a></article>`).join('')||'<p>Không tìm thấy văn bản phù hợp.</p>'}
function renderSuggestions(topic='all'){const items=topic==='all'?qa.slice(0,6):qa.filter(x=>x.topic===topic);$('#suggestions').innerHTML=items.map((x,i)=>`<button class="suggestion" data-q="${x.q}"><span>0${i+1}</span>${x.q}</button>`).join('');$$('.suggestion').forEach(b=>b.onclick=()=>ask(b.dataset.q))}
function normalize(s){return s.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'')}
function findAnswer(q){const n=normalize(q);let best=null,score=0;qa.forEach(x=>{let s=x.keys.reduce((a,k)=>a+(n.includes(normalize(k))?3:0),0);normalize(x.q).split(' ').forEach(w=>{if(w.length>4&&n.includes(w))s++});if(s>score){score=s;best=x}});return score>=2?best:null}
function ask(text){const q=text.trim();if(!q)return;$('#welcome').style.display='none';$('#suggestions').style.display='none';const chat=$('#chat');chat.insertAdjacentHTML('beforeend',`<div class="message user">${q.replace(/[<>]/g,'')}</div>`);const a=findAnswer(q);setTimeout(()=>{chat.insertAdjacentHTML('beforeend',a?`<div class="message bot"><div class="answer-label">PHÂN TÍCH PHÁP LÝ</div><h3>${a.title}</h3><p>${a.answer}</p><p><a class="citation" href="#library">§ ${a.cite}</a></p><div class="action-box"><b>Việc nên làm</b><p>${a.action}</p></div></div>`:`<div class="message bot"><div class="answer-label">CẦN THÊM THÔNG TIN</div><h3>Tình huống này cần được mô tả cụ thể hơn.</h3><p>Bạn vui lòng cho biết loại hợp đồng, các bên tham gia, cách ký/xác thực và vấn đề bạn muốn xác định. Bạn cũng có thể chọn một câu hỏi gợi ý theo chủ đề.</p><div class="action-box"><b>Lưu ý</b><p>Phiên bản hiện tại dùng kho tri thức tuyển chọn và không thay thế ý kiến luật sư.</p></div></div>`);chat.lastElementChild.scrollIntoView({behavior:'smooth',block:'center'})},300);$('#question').value=''}
$$('.nav-link').forEach(b=>b.onclick=()=>{$$('.nav-link,.view').forEach(x=>x.classList.remove('active'));b.classList.add('active');$('#'+b.dataset.view).classList.add('active');scrollTo(0,0)});
$$('.topic').forEach(b=>b.onclick=()=>{$$('.topic').forEach(x=>x.classList.remove('active'));b.classList.add('active');renderSuggestions(b.dataset.topic)});
$('#askForm').onsubmit=e=>{e.preventDefault();ask($('#question').value)};$('#question').onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();$('#askForm').requestSubmit()}};$('#sourceSearch').oninput=e=>renderSources(e.target.value);
function renderChecks(){let saved=JSON.parse(localStorage.getItem('ect-checks')||'[]');$('#checkItems').innerHTML=checklist.map((x,i)=>`<label class="check-item"><input type="checkbox" data-i="${i}" ${saved.includes(i)?'checked':''}><span><b>${x[0]}</b><p>${x[1]}</p></span></label>`).join('');$$('.check-item input').forEach(x=>x.onchange=()=>{saved=$$('.check-item input:checked').map(x=>+x.dataset.i);localStorage.setItem('ect-checks',JSON.stringify(saved));updateScore(saved.length)});updateScore(saved.length)}
function updateScore(n){$('#score').textContent=`${n}/8 hoàn tất`;const el=$('#checkResult');if(n===8)el.innerHTML='<span>✓</span><div><b>Đã hoàn thành kiểm tra nền tảng</b><p>Hồ sơ có nền tảng chứng cứ tốt. Vẫn cần rà soát luật chuyên ngành và nội dung cụ thể trước khi ký.</p></div>';else if(n>=5)el.innerHTML='<span>→</span><div><b>Còn một vài điểm cần hoàn thiện</b><p>Ưu tiên các mục chưa đánh dấu trước khi gửi hợp đồng để ký.</p></div>';else el.innerHTML='<span>!</span><div><b>Chưa đủ dữ liệu để đánh giá</b><p>Hoàn thành checklist để nhận khuyến nghị.</p></div>'}
renderSuggestions();renderSources();renderChecks();
